/**
 * The frozen BoundaryCI Octokit analyzer compatibility profile.
 *
 * This module is a first-party projection of the already reviewed Phase 1 operation
 * inventory (`tools/permission-data-feasibility/evidence/operation-inventory.json`, content
 * digest {@link INVENTORY_CONTENT_SHA256}). Nothing here is read from a package, a file, or
 * a network service at analysis time, and no endpoint identity is ever derived from a
 * method name by heuristic.
 *
 * Two independent projections are pinned:
 *
 * - {@link ANALYZER_ENDPOINT_PROFILE}`.members` — the 1,010 endpoint-method rows whose
 *   surface is identical across the reviewed v17 and v18 surfaces *and* whose OpenAPI
 *   operation join is unique. Each row carries exactly one v18 route and exactly one
 *   operation ID, so `scope.method` maps unambiguously to one canonical REST operation.
 * - {@link ANALYZER_ENDPOINT_PROFILE}`.operations` — the 878 App-enabled OpenAPI operation
 *   rows of the same inventory.
 *
 * Recognizing a member here is a *source-compatibility* claim about the pinned
 * `octokit@5.0.5` / `@octokit/plugin-rest-endpoint-methods@18.0.0` surface. BoundaryCI does
 * not inspect, install, resolve, or verify the analyzed repository's runtime Octokit
 * version, and profile membership never authorizes a permission-catalog row: permission
 * authority lives only in `src/permission-model/bounded-catalog.ts`.
 */

function deepFreeze<T>(value: T): T {
  if (value !== null && typeof value === 'object') {
    for (const child of Object.values(value as Record<string, unknown>)) deepFreeze(child);
    Object.freeze(value);
  }
  return value;
}

/** Content digest of the reviewed operation inventory these rows were projected from. */
const INVENTORY_CONTENT_SHA256 = 'ce52c93c636e725b40dde745b9e435ef01e26cda39c53510842c43eaaa5c4ff4';

