const ARTIFACT_MANIFEST_SHA256 = 'ffe2270a26567042f146e0ec982a7343de51a1f6333f2de6fa0421aca1e4c94c';

/** One exact `scope.method` endpoint member and the single REST operation it denotes. */
export interface EndpointMemberRecord {
  scope: string;
  method: string;
  httpMethod: string;
  normalizedRoute: string;
  operationId: string;
}

/** One App-enabled REST operation from the pinned inventory. */
export interface ProfileOperationRecord {
  method: string;
  normalizedRoute: string;
  operationId: string;
}

/** Versioned identity of this profile, recorded in every analysis result. */
export interface AnalyzerProfileIdentity {
  schemaVersion: number;
  profileId: string;
  octokitVersion: string;
  endpointMethodsVersion: string;
  restApiVersion: string;
  inventoryContentSha256: string;
  artifactManifestSha256: string;
  endpointMemberCount: number;
  operationCount: number;
}

