export interface AnalyzerEndpointProfile {
  identity: Readonly<AnalyzerProfileIdentity>;
  members: readonly EndpointMemberRecord[];
  operations: readonly ProfileOperationRecord[];
}

/** The complete pinned profile: its identity and both deterministic projections. */
export const ANALYZER_ENDPOINT_PROFILE: Readonly<AnalyzerEndpointProfile> = deepFreeze({
  identity: ANALYZER_PROFILE_IDENTITY,
  members: ENDPOINT_MEMBERS,
  operations: APP_ENABLED_OPERATIONS,
});

/**
 * Alternate `receiver.<scope>.<method>(...)` surfaces authorized as exactly equivalent to
 * the canonical `receiver.rest.<scope>.<method>(...)` spelling.
 *
 * The set is empty: no pinned artifact in this repository proves that equivalence, and
 * real-world frequency is prioritization evidence rather than authorization. A call in that
 * shape therefore stays an explicit unsupported candidate instead of becoming an operation.
 */
export const DIRECT_SHORTHAND_AUTHORIZATIONS: readonly EndpointMemberRecord[] = deepFreeze([]);

/**
 * Endpoint members whose function may be detached from its receiver without changing
 * operation semantics.
 *
 * The set is empty: no pinned surface evidence in this repository proves detachment-safety,
 * and JavaScript shape alone is not evidence.
 */
export const DETACHED_ENDPOINT_AUTHORIZATIONS: readonly EndpointMemberRecord[] = deepFreeze([]);
